    /// <summary>Crate</summary>
    private static void Create004_Crate(Scene scene)
    {
        var o3 = new GameObject(Primitives.Cube(1f), 2f, 0.5f, -3f)
        { Name = "Crate", Tag = "spinner" };
        o3.AddScript(new global::Spin
        {
            DegreesPerSecond = 40f,
        });
        var o4 = new GameObject(Primitives.Sphere(0.18f, 16), 0f, 1.1f, 0f)
        { Name = "Moon" };
        o4.Material.Color = new Color4(0.827451f, 0.827451f, 0.827451f, 1f);
        o3.AddChild(o4);
        scene.Add(o3);
    }

    /// <summary>Model</summary>
    private static void Create005_Model(Scene scene)
    {
        var o5 = new GameObject(GT67.Utils.Assets.LoadModel("Assets/Game/Models/pyramid/pyramid.obj"), -4f, 0f, -4f)
        { Name = "Model" };
        o5.Scale = new Vector3(2f, 2f, 2f);
        scene.Add(o5);
    }

    /// <summary>Sphere</summary>
    private static void Create006_Sphere(Scene scene)
    {
        var o6 = new GameObject(Primitives.Sphere(0.75f, 48), -2.5f, 0.75f, -1f)
        { Name = "Sphere" };
        o6.Material.Color = new Color4(0.39215687f, 0.58431375f, 0.92941177f, 1f);
        o6.Material.Shininess = 128f;
        scene.Add(o6);
    }

    /// <summary>Cylinder</summary>
    private static void Create007_Cylinder(Scene scene)
    {
        var o7 = new GameObject(Primitives.Cylinder(0.5f, 1.4f, 32), 0.5f, 0.7f, -1f)
        { Name = "Cylinder" };
        o7.Material.Color = new Color4(0.19607843f, 0.8039216f, 0.19607843f, 1f);
        scene.Add(o7);
    }

    /// <summary>Torus</summary>
    private static void Create008_Torus(Scene scene)
    {
        var o8 = new GameObject(Primitives.Torus(0.6f, 0.2f, 40, 20), 3.5f, 0.8f, 0.5f)
        { Name = "Torus" };
        o8.EulerAngles = new Vector3(60f, 0f, 0f);
        o8.Material.Color = new Color4(1f, 0.4117647f, 0.7058824f, 1f);
        scene.Add(o8);
    }

    /// <summary>Cone</summary>
    private static void Create009_Cone(Scene scene)
    {
        var o9 = new GameObject(Primitives.Cone(0.5f, 1.2f, 32), -1.5f, 0.6f, 2.5f)
        { Name = "Cone" };
        o9.Material.Color = new Color4(1f, 0.84313726f, 0f, 1f);
        scene.Add(o9);
    }

    /// <summary>Player</summary>
    private static void Create010_Player(Scene scene)
    {
        var o10 = new GameObject(Primitives.Capsule(0.35f, 1.8f, 24), 1.5f, 0.9f, 2.5f)
        { Name = "Player", Tag = "Player" };
        o10.Material.Color = new Color4(0.5764706f, 0.4392157f, 0.85882354f, 1f);
        o10.AddScript(new global::PlayerController
        {
            Radius = 0.35f,
            SphereOffset = -0.54999995f,
        });
        scene.Add(o10);
    }

    /// <summary>Camera</summary>
    private static void Create011_Camera(Scene scene)
    {
        var o11 = new GameObject(Primitives.CameraBody(0.6f), 1.5f, 3.4f, 8.5f)
        { Name = "Camera", CastShadow = false, Collision = global::GT67.Core.CollisionMode.None };
        o11.EulerAngles = new Vector3(-22.619864f, 0f, -0f);
        o11.Material.Color = new Color4(0.2f, 0.22f, 0.26f, 1f);
        o11.AddScript(new global::GameCamera
        {
        });
        scene.Add(o11);
    }

    /// <summary>Glass</summary>
    private static void Create012_Glass(Scene scene)
    {
        var o12 = new GameObject(Primitives.Sphere(0.9f, 32), 0f, 0.9f, 4f)
        { Name = "Glass", CastShadow = false };
        o12.Material.Color = new Color4(0f, 1f, 1f, 1f);
        o12.Material.Opacity = 0.35f;
        scene.Add(o12);
    }

    /// <summary>Axes</summary>
    private static void Create013_Axes(Scene scene)
    {
        var o13 = new GameObject(Primitives.Axes(1.5f), 0f, 0.02f, 0f)
        { Name = "Axes", CastShadow = false, Collision = global::GT67.Core.CollisionMode.None };
        o13.Material.Unlit = true;
        scene.Add(o13);
    }

    /// <summary>Rock</summary>
    private static void Create014_Rock(Scene scene)
    {
        var o14 = new GameObject(Primitives.Sphere(0.9f, 24), 6.4f, -0.35f, -3.4f)
        { Name = "Rock" };
        o14.Scale = new Vector3(1.1f, 0.8f, 1f);
        o14.Material.Color = new Color4(0.45f, 0.45f, 0.48f, 1f);
        o14.Material.Shininess = 8f;
        scene.Add(o14);
    }
    private static Mesh BakedMesh(string vertices, string indices) =>
        new(MemoryMarshal.Cast<byte, Vertex>(Convert.FromBase64String(vertices)).ToArray(),
            MemoryMarshal.Cast<byte, uint>(Convert.FromBase64String(indices)).ToArray());
}
